create or replace function preview_schedule_move_v1(p_schedule_id uuid,p_weekday smallint,p_period smallint,p_classroom_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$declare r teacher_schedule%rowtype;ok boolean:=false;msg text;begin perform open_permission_context('schedule.edit');select * into r from teacher_schedule where id=p_schedule_id and active=true;if not found then raise exception 'SCHEDULE_ROW_NOT_FOUND';end if;begin perform upsert_schedule_slot_permission_core_v2(r.teacher_assignment_id,p_weekday,p_period,coalesce(p_classroom_id,r.classroom_id),r.subgroup_id,r.id,r.locked,'manual');ok:=true;raise exception using errcode='P0001',message='OKULOS_PREVIEW_ROLLBACK';exception when others then if SQLERRM='OKULOS_PREVIEW_ROLLBACK' and ok then return jsonb_build_object('ok',true,'schedule_id',p_schedule_id,'weekday',p_weekday,'period',p_period);else msg:=SQLERRM;return jsonb_build_object('ok',false,'error',msg,'schedule_id',p_schedule_id,'weekday',p_weekday,'period',p_period);end if;end;end$$;
create or replace function move_schedule_slot_v1(p_schedule_id uuid,p_weekday smallint,p_period smallint,p_classroom_id uuid default null) returns uuid language plpgsql security definer set search_path=public as $$declare r teacher_schedule%rowtype;v uuid;begin perform open_permission_context('schedule.edit');select * into r from teacher_schedule where id=p_schedule_id and active=true for update;if not found then raise exception 'SCHEDULE_ROW_NOT_FOUND';end if;perform create_schedule_restore_point('Elle taşıma öncesi','Ders programı sürükle-bırak güvenlik noktası');v:=upsert_schedule_slot_permission_core_v2(r.teacher_assignment_id,p_weekday,p_period,coalesce(p_classroom_id,r.classroom_id),r.subgroup_id,r.id,r.locked,'manual');return v;end$$;